mapper.select:
SELECT 


ORDER BY ticket_item.create_time DESC, ticket_item.id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE ticket
SET assignee_id = #{assigneeId},
    status = #{toStatus},
    version = version + 1,
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{fromStatus}
  AND version = #{version}

UPDATE ticket
SET status = #{toStatus},
    version = version + 1,
    update_time = CURRENT_TIMESTAMP

    , resolved_time = #{resolvedTime}


    , closed_time = #{closedTime}

WHERE id = #{id}
  AND status = #{fromStatus}
  AND version = #{version}
